// 🤖 Fails the build when the built tour is missing or broken.
//
// hack/gen-tour.mjs checks tour.json's shape before Eleventy runs; this
// checks what Eleventy made of it: a page per step at the URL the step
// list links to, every link between them resolving, each step's zip
// actually in the site, each file's changed lines marked, and nothing
// loaded from another origin.
//
// It also says where the tour came from. A build from --from (the
// fixture, or a directory someone generated by hand) passes, but says
// so on its success line, so it cannot be mistaken for a build from
// tourgen at the docs' sha.
import { readFileSync, statSync } from "node:fs";
import { join } from "node:path";

const site = "_site";
const problems = [];
const fail = (m) => problems.push(m);
const exists = (p) => {
  try {
    statSync(p);
    return true;
  } catch {
    return false;
  }
};
const read = (p) => {
  try {
    return readFileSync(p, "utf8");
  } catch {
    return null;
  }
};
// The file a site-absolute URL is served from.
const fileFor = (url) => {
  const path = url.split("#")[0].split("?")[0];
  return join(site, path.endsWith("/") ? path + "index.html" : path);
};

let receipt;
try {
  receipt = JSON.parse(readFileSync("_tour/.tourgen-source.json", "utf8"));
} catch {
  console.error("tour check: _tour/.tourgen-source.json is missing — run node hack/gen-tour.mjs");
  process.exit(1);
}
const tour = JSON.parse(readFileSync("_tour/tour.json", "utf8"));

let source;
if (receipt.from) {
  source = `copied from ${receipt.from}, NOT generated by tourgen`;
} else {
  const { sha } = JSON.parse(readFileSync("src/_data/docsversion.json", "utf8"));
  if (receipt.sha !== sha) {
    fail(`the tour was generated from ${receipt.sha}, but the docs are at ${sha}; rebuild`);
  }
  source = `from tourgen at ${receipt.short}`;
}
if (receipt.steps !== tour.steps.length) {
  fail(`the receipt names ${receipt.steps} steps, tour.json has ${tour.steps.length}; rebuild`);
}

for (const asset of ["tour.css", "tour.js"]) {
  if (!exists(join(site, asset))) fail(`/${asset} is missing from ${site}`);
}

// Resources a page loads (not links a reader follows) must be same-origin.
const foreign = (html) =>
  [...html.matchAll(/<(?:script|link|img|iframe|source|video|audio)\b[^>]*\b(?:src|href)="([^"]+)"/g)]
    .map((m) => m[1])
    .filter((url) => /^(?:[a-z]+:)?\/\//i.test(url));

const hrefs = (html) => [...html.matchAll(/\bhref="(\/[^"]*)"/g)].map((m) => m[1]);
const checkLinks = (where, html) => {
  for (const url of hrefs(html)) {
    if (!exists(fileFor(url))) fail(`${where}: link to ${url} goes nowhere`);
  }
  for (const url of foreign(html)) fail(`${where}: loads ${url} from another origin`);
};

const index = read(join(site, "tour", "index.html"));
if (index === null) {
  fail("/tour/ was not built");
} else {
  checkLinks("/tour/", index);
}

const lines = (ranges) => ranges.reduce((n, [first, last]) => n + last - first + 1, 0);
const urlOf = (step) => `/tour/${tour.slug}/${String(step.number).padStart(2, "0")}-${step.slug}/`;
if (index !== null && !index.includes(`href="${urlOf(tour.steps[0])}"`)) {
  fail("/tour/ does not link to the first step");
}

for (const step of tour.steps) {
  const url = urlOf(step);
  const html = read(fileFor(url));
  if (html === null) {
    fail(`${url} was not built`);
    continue;
  }
  checkLinks(url, html);
  if (!/<h1><span class="ai">🤖<\/span>/.test(html)) fail(`${url}: the title carries no visible 🤖`);
  if (step.zip && !html.includes(`href="/tour/zips/${step.zip}"`)) fail(`${url}: no download link for ${step.zip}`);
  if (!html.includes(`${step.number} / ${tour.steps.length}`)) fail(`${url}: no progress indicator`);
  if (step.check && !html.includes('id="check-h"')) fail(`${url}: the "Check it worked" box is missing`);

  // One panel per file, each with exactly its changed lines marked.
  // Panels are numbered in file order, and nothing else on the page
  // carries a code-file-N id, so slicing between them is safe.
  step.files.forEach((file, i) => {
    const start = html.indexOf(`id="code-file-${i + 1}"`);
    if (start === -1) {
      fail(`${url}: ${file.path} has no code panel`);
      return;
    }
    const end = html.indexOf("</pre>", start);
    const panel = html.slice(start, end);
    const marked = (panel.match(/class="ln hl"/g) ?? []).length;
    const want = lines(file.changed);
    if (marked !== want) fail(`${url}: ${file.path} marks ${marked} changed lines, tour.json says ${want}`);
  });
  if (!step.files.length && html.includes('class="mk editor"')) fail(`${url}: an editor with no files`);
  for (const command of step.commands) {
    // Escaped as Nunjucks escapes it.
    const escaped = command
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
    if (!html.includes(`<span class="c">${escaped}</span>`)) fail(`${url}: the command "${command}" is missing`);
  }
}

if (problems.length) {
  console.error(`tour check: ${problems.length} problem(s)`);
  for (const p of problems) console.error(`  - ${p}`);
  process.exit(1);
}
console.log(`tour ok: "${tour.title}", ${tour.steps.length} steps, ${source}`);
